82	  await requireAdmin();
83	  const apps = await db.app.findMany({
84	    orderBy: { createdAt: "asc" },
85	    include: { _count: { select: { boards: true } }, server: { select: { id: true, name: true, status: true } } },
86	  });
87	  return apps.map((a) => ({
