164	/** All boards, oldest first. Optionally filtered to one app. Seeds a default
165	 *  "Nxeon" board (attached to the Nxeon app when present) on first use. */
166	export async function listBoards(appId?: string | null): Promise<BoardSummary[]> {
167	  await requireAdmin();
168	  const where = appId ? { appId } : {};
169	  let boards = await db.board.findMany({ where, orderBy: { createdAt: "asc" }, include: { _count: { select: { cards: true } } } });
170	  // Only seed when the whole board table is empty (never when a filter just
171	  // happens to match nothing).
172	  if (!appId && (await db.board.count()) === 0) {
173	    const nxeonApp = await db.app.findUnique({ where: { slug: "nxeon" } });
174	    await createBoardInternal("Nxeon", nxeonApp?.id ?? null);
175	    boards = await db.board.findMany({ where, orderBy: { createdAt: "asc" }, include: { _count: { select: { cards: true } } } });
176	  }
177	  return boards.map((b) => ({ id: b.id, name: b.name, cardCount: b._count.cards, appId: b.appId }));
178	}
