180	async function createBoardInternal(name: string, appId?: string | null): Promise<string> {
181	  const board = await db.board.create({ data: { name, appId: appId ?? null } });
182	  await db.boardColumn.createMany({ data: DEFAULT_COLUMNS.map((n, i) => ({ boardId: board.id, name: n, position: i })) });
183	  return board.id;
