253	export async function createColumn(boardId: string, name: string): Promise<void> {
254	  await requireAdmin();
255	  const clean = String(name ?? "").trim().slice(0, 40);
256	  if (!clean) return;
257	  const max = await db.boardColumn.aggregate({ where: { boardId }, _max: { position: true } });
258	  await db.boardColumn.create({ data: { boardId, name: clean, position: (max._max.position ?? -1) + 1 } });
