297	/** Full-text-ish search over card title, description and comment bodies
298	 *  (Postgres case-insensitive contains). Scoped to a board, or to an app (all
299	 *  its boards). Skips archived cards. */
300	export async function searchCards(
301	  scope: { boardId?: string | null; appId?: string | null },
302	  query: string,
303	): Promise<CardSearchHit[]> {
304	  await requireAdmin();
305	  const q = String(query ?? "").trim();
306	  if (q.length < 2) return [];
307	  const boardWhere =
308	    scope.boardId ? { boardId: scope.boardId } : scope.appId ? { board: { appId: scope.appId } } : {};
309	  const cards = await db.card.findMany({
310	    where: {
311	      archivedAt: null,
312	      ...boardWhere,
313	      OR: [
314	        { title: { contains: q, mode: "insensitive" } },
315	        { description: { contains: q, mode: "insensitive" } },
316	        { comments: { some: { body: { contains: q, mode: "insensitive" } } } },
317	      ],
318	    },
319	    include: {
320	      board: { select: { name: true } },
321	      column: { select: { name: true } },
322	      comments: { where: { body: { contains: q, mode: "insensitive" } }, take: 1, orderBy: { createdAt: "desc" } },
323	    },
324	    orderBy: { updatedAt: "desc" },
325	    take: 50,
326	  });
327	  const lower = q.toLowerCase();
328	  const snippetAround = (text: string): string => {
329	    const i = text.toLowerCase().indexOf(lower);
330	    if (i < 0) return text.slice(0, 120);
331	    const start = Math.max(0, i - 40);
332	    return (start > 0 ? "…" : "") + text.slice(start, i + q.length + 60).trim() + (i + q.length + 60 < text.length ? "…" : "");
333	  };
334	  return cards.map((c) => {
335	    let matchedIn: CardSearchHit["matchedIn"] = "title";
336	    let snippet = c.title;
337	    if (!c.title.toLowerCase().includes(lower)) {
338	      if (c.description.toLowerCase().includes(lower)) {
339	        matchedIn = "description";
340	        snippet = snippetAround(c.description);
341	      } else if (c.comments[0]) {
342	        matchedIn = "comment";
343	        snippet = snippetAround(c.comments[0].body);
344	      }
345	    }
346	    return {
347	      id: c.id,
348	      boardId: c.boardId,
349	      boardName: c.board.name,
350	      columnId: c.columnId,
351	      columnName: c.column.name,
352	      title: c.title,
353	      type: c.type,
354	      priority: c.priority,
355	      snippet,
356	      matchedIn,
357	    };
358	  });
359	}
