const TYPE_TONE: Record<string, string> = {
  IDEA: "bg-sky-500/15 text-sky-300",
  FEATURE: "bg-brand-500/15 text-brand-200",
  BUG: "bg-red-500/15 text-red-300",
  CHORE: "bg-slate-500/20 text-slate-300",
};
const PRIORITY_DOT: Record<string, string> = { LOW: "bg-slate-500", NORMAL: "bg-sky-400", HIGH: "bg-amber-400", URGENT: "bg-red-400" };
// Colour of the little status dot next to a bound server's name.
const SERVER_STATUS_DOT: Record<string, string> = {
  RUNNING: "bg-emerald-400",
  PROVISIONING: "bg-sky-400",
  REINSTALLING: "bg-sky-400",
  PENDING: "bg-amber-400",
  STOPPED: "bg-slate-500",
  SUSPENDED: "bg-amber-500",
  DELETING: "bg-red-400",
  ERROR: "bg-red-500",
};
const PRIORITY_RANK: Record<string, number> = { URGENT: 3, HIGH: 2, NORMAL: 1, LOW: 0 };
const TYPES = ["IDEA", "FEATURE", "BUG", "CHORE"];
const PRIORITIES = ["LOW", "NORMAL", "HIGH", "URGENT"];

// Deterministic chip colour for a label so the same label always looks the same.
const LABEL_PALETTE = [
  "bg-rose-500/15 text-rose-300", "bg-amber-500/15 text-amber-300", "bg-emerald-500/15 text-emerald-300",
  "bg-sky-500/15 text-sky-300", "bg-violet-500/15 text-violet-300", "bg-teal-500/15 text-teal-300",
  "bg-fuchsia-500/15 text-fuchsia-300", "bg-lime-500/15 text-lime-300",
];
function labelColor(label: string): string {
  let h = 0;
  for (let i = 0; i < label.length; i++) h = (h * 31 + label.charCodeAt(i)) >>> 0;
  return LABEL_PALETTE[h % LABEL_PALETTE.length];
}
function relativeTime(iso: string): string {
  const then = new Date(iso).getTime();
  const s = Math.max(0, Math.floor((Date.now() - then) / 1000));
  if (s < 60) return "just now";
  const m = Math.floor(s / 60);
  if (m < 60) return `${m}m ago`;
  const h = Math.floor(m / 60);
  if (h < 24) return `${h}h ago`;
  const d = Math.floor(h / 24);
  if (d < 30) return `${d}d ago`;
  return new Date(iso).toLocaleDateString();
}
/** Split text around the first case-insensitive match of `q`, wrapping the match. */
function highlight(text: string, q: string) {
  if (!q) return text;
  const i = text.toLowerCase().indexOf(q.toLowerCase());
  if (i < 0) return text;
  return (
    <>
      {text.slice(0, i)}
      <mark className="rounded bg-amber-400/30 text-amber-100">{text.slice(i, i + q.length)}</mark>
      {text.slice(i + q.length)}
    </>
  );
}

type DragState = { kind: "card"; id: string } | { kind: "column"; id: string } | null;

export function BoardClient({
  apps,
  boards,
  board,
  activeApp,
  unassignedCount,
}: {
  apps: AppSummary[];
  boards: BoardSummary[];
  board: BoardData | null;
  activeApp: string | null;
  unassignedCount: number;
}) {
  const router = useRouter();
  const [openCard, setOpenCard] = useState<string | null>(null);
  const [appSettingsOpen, setAppSettingsOpen] = useState(false);
  const [drag, setDrag] = useState<DragState>(null);
  // Local column state for optimistic moves.
  const [cols, setCols] = useState<ColumnData[]>(board?.columns ?? []);
  useEffect(() => setCols(board?.columns ?? []), [board?.id, board?.columns]);

  // Which column currently has its inline quick-add open (also driven by the "n"
  // keyboard shortcut, which opens the first column's adder).
  const [addingCol, setAddingCol] = useState<string | null>(null);
  const [trashHot, setTrashHot] = useState(false);

  // Filter + sort state.
  const [fType, setFType] = useState("");
  const [fPriority, setFPriority] = useState("");
  const [fAssignee, setFAssignee] = useState("");
  const [fLabel, setFLabel] = useState("");
  const [sortBy, setSortBy] = useState<"manual" | "priority" | "updated" | "title">("manual");
  const filterActive = Boolean(fType || fPriority || fAssignee || fLabel);
  const dragEnabled = sortBy === "manual" && !filterActive;

  // Search state (debounced), scoped to the current board.
  const [searchQ, setSearchQ] = useState("");
  const [hits, setHits] = useState<CardSearchHit[]>([]);
  const searchRef = useRef<HTMLInputElement>(null);
  useEffect(() => {
    const q = searchQ.trim();
    if (q.length < 2 || !board) { setHits([]); return; }
    let live = true;
    const t = setTimeout(async () => {
      const res = await searchCards({ boardId: board.id }, q);
      if (live) setHits(res);
    }, 220);
    return () => { live = false; clearTimeout(t); };
  }, [searchQ, board]);

  // Options for the filter dropdowns, drawn from the loaded board.
  const allCards = cols.flatMap((c) => c.cards);
  const assigneeOptions = Array.from(new Set(allCards.map((c) => c.assignee).filter(Boolean))) as string[];
  const labelOptions = Array.from(new Set(allCards.flatMap((c) => c.labels))).sort();

  function visibleCards(col: ColumnData): CardSummary[] {
    let list = col.cards.filter(
      (c) =>
        (!fType || c.type === fType) &&
        (!fPriority || c.priority === fPriority) &&
        (!fAssignee || c.assignee === fAssignee) &&
        (!fLabel || c.labels.includes(fLabel)),
    );
    if (sortBy === "priority") list = [...list].sort((a, b) => PRIORITY_RANK[b.priority] - PRIORITY_RANK[a.priority]);
    else if (sortBy === "updated") list = [...list].sort((a, b) => b.updatedAt.localeCompare(a.updatedAt));
    else if (sortBy === "title") list = [...list].sort((a, b) => a.title.localeCompare(b.title));
    return list;
  }

  // Build a board URL that preserves the current app filter.
  const appQuery = activeApp ? `&app=${encodeURIComponent(activeApp)}` : "";
  const boardHref = (id: string) => `/admin/board?b=${id}${appQuery}`;
  const appHref = (id: string | null) => (id ? `/admin/board?app=${encodeURIComponent(id)}` : "/admin/board");

  async function newBoard() {
    const name = prompt("New board name (e.g. Soul Pilates)");
    if (!name?.trim()) return;
    // New boards inherit the currently selected app (unless "unassigned"/all).
    const appId = activeApp && activeApp !== "unassigned" ? activeApp : null;
    const res = await createBoard(name.trim(), appId);
    if (res.id) router.push(boardHref(res.id));
  }

  async function newApp() {
    const name = prompt("New app / product name (e.g. Soul Pilates)");
    if (!name?.trim()) return;
    const res = await createApp(name.trim());
    if (res.id) router.push(appHref(res.id));
    else if (res.error) alert(res.error);
  }

  // The real app currently selected (a bound-server picker only makes sense for a
  // concrete app, not the "All"/"Unassigned" pseudo-filters).
  const selectedApp = activeApp && activeApp !== "unassigned" ? apps.find((a) => a.id === activeApp) ?? null : null;
  // Real servers the selected app can be bound to. Fetched lazily the first time
  // a concrete app is in view; admin-gated on the server.
  const [servers, setServers] = useState<ServerOption[] | null>(null);
  useEffect(() => {
    if (!selectedApp || servers !== null) return;
    let live = true;
    listServersForBinding().then((s) => { if (live) setServers(s); }).catch(() => undefined);
    return () => { live = false; };
  }, [selectedApp, servers]);

  async function onPickServer(appId: string, serverId: string) {
    const res = await setAppServer(appId, serverId || null);
    if (res.error) { alert(res.error); return; }
    router.refresh();
  }

  // Move a card into `colId` at `index` (index is against the column's true,
  // unfiltered order — drag is only enabled when the view is unfiltered/manual).
  async function onDropCard(colId: string, index: number) {
    if (!drag || drag.kind !== "card") return;
    const cardId = drag.id;
    setDrag(null);
    setCols((prev) => {
      let moved: CardSummary | undefined;
      const stripped = prev.map((c) => ({ ...c, cards: c.cards.filter((cd) => (cd.id === cardId ? ((moved = cd), false) : true)) }));
      if (!moved) return prev;
      return stripped.map((c) => (c.id === colId ? { ...c, cards: [...c.cards.slice(0, index), moved!, ...c.cards.slice(index)] } : c));
    });
    await moveCard(cardId, colId, index);
  }

  // Reorder a column to `targetIndex` (drag a column by its header).
  async function onDropColumn(targetIndex: number) {
    if (!drag || drag.kind !== "column") return;
    const colId = drag.id;
    setDrag(null);
    let optimistic: ColumnData[] = cols;
    setCols((prev) => {
      const from = prev.findIndex((c) => c.id === colId);
      if (from < 0) return prev;
      const next = [...prev];
      const [moved] = next.splice(from, 1);
      const idx = Math.max(0, Math.min(targetIndex, next.length));
      next.splice(idx, 0, moved);
      optimistic = next;
      return next;
    });
    // Translate the visual target into the DB index (position among the others).
    const finalIndex = optimistic.findIndex((c) => c.id === colId);
    await moveColumn(colId, Math.max(0, finalIndex));
  }

  async function trashCard() {
    if (!drag || drag.kind !== "card") return;
    const cardId = drag.id;
    setDrag(null);
    setTrashHot(false);
    if (!confirm("Delete this card permanently? This removes its attachments and comments and cannot be undone.")) return;
    setCols((prev) => prev.map((c) => ({ ...c, cards: c.cards.filter((cd) => cd.id !== cardId) })));
    await deleteCard(cardId);
    router.refresh();
  }

  // Keyboard shortcuts: "/" focuses search, "n" opens the first column's quick-add.
