/**
 * Admin/staff action modules behind the admin portal, and the guard each of their
 * privileged exports is expected to reach for. Files not in
 * customer-actions-guards' list. Every listed module carries `"use server"`.
 */
const ADMIN_ACTION_FILES = [
  "actions-admin-billing.ts",
  "actions-accounting.ts",
  "actions-staff.ts",
  "actions-nodes.ts",
  "actions-abuse.ts",
  "actions-blog.ts",
  "actions-chat.ts",
  "actions-testimonials.ts",
  "actions-gift.ts",
  "actions-games.ts",
  "actions-improvements.ts",
  "actions-email-templates.ts",
