  "actions-newsletter-campaign.ts",
  "actions-ovh.ts",
  "actions-billing.ts",
  "actions-feedback.ts",
  "actions-account.ts",
  "actions-reddit-templates.ts",
  "actions-company-mail.ts",
] as const;

/**
 * Exports that are SUPPOSED to answer without a require* guard, each with the
 * reason. `requestPasswordReset`/`resetPassword` are the public forgot-password
 * flow (token-gated, like register/login). `stopImpersonating` only clears the
 * CALLER's own impersonation cookie — it removes privilege, never grants it.
 */
const INTENTIONALLY_UNGUARDED = new Set([
  "actions-account.ts:requestPasswordReset",
  "actions-account.ts:resetPassword",
  "actions-account.ts:stopImpersonating",
]);

test("every admin/staff server action identifies its caller inside the function", () => {
  const unguarded: string[] = [];
  for (const file of ADMIN_ACTION_FILES) {
    const src = source(file);
    assert.ok(src.includes('"use server"'), `${file} should declare "use server"`);
    for (const name of exportedActions(src)) {
      const key = `${file}:${name}`;
      if (INTENTIONALLY_UNGUARDED.has(key)) continue;
      if (!AUTH_MARKERS.some((m) => bodyOf(src, name).includes(m))) unguarded.push(key);
    }
  }
  assert.deepEqual(
    unguarded,
    [],
    "these admin endpoints are network-reachable with no caller check inside the function",
  );
});

