 * code, or match the note and fail on correct code. Either way it teaches people
 * to ignore it. These assertions look at what the file DOES.
 */
function code(relative: string): string {
  return readFileSync(new URL(relative, import.meta.url), "utf8")
    .replace(/\/\*[\s\S]*?\*\//g, "")
    .replace(/^\s*\/\/.*$/gm, "");
