/* ================================================================== *
 * H6. Any customer who enables 2FA is permanently locked out
 *
 * The login email input was UNCONTROLLED while the password beside it was
 * controlled. React 19 resets uncontrolled fields after a form action settles,
 * and the 2FA path submits the SAME form twice: pass 1 returns `needs2fa`, pass
 * 2 must re-send email + password + code. React blanked the email between them,
 * `credsSchema` rejected the empty string, and the reply was a bare "Invalid
 * email or password." with no `needs2fa` — which unmounted the code field. With
 * correct credentials, there was no way through. Ever.
 * ================================================================== */

/**
 * Every USER-EDITABLE `<input>` in the file, as source text. All are self-closing.
 *
 * `type="hidden"` is excluded deliberately. The invariant below is that a field
 * the customer TYPED INTO survives a rejected submit — React 19 blanks
 * uncontrolled fields on every form action, which is what permanently locked
 * people out of 2FA. A hidden field is never typed into: it carries a value the
 * page already knows (the post-login destination), so `value=` with no `onChange`
 * is exactly right there, and demanding a change handler for it would be
 * cargo-culting the rule past the reason for it.
 */
function inputTags(src: string): string[] {
  return [...src.matchAll(/<input\b[\s\S]*?\/>/g)]
    .map((m) => m[0])
    .filter((tag) => !/type="hidden"/.test(tag));
}

test("H6: every input on the auth forms is controlled, so nothing survives on luck", () => {
  const tags = inputTags(AUTH_FORMS);
  assert.ok(tags.length >= 5, `expected the auth forms' inputs, found ${tags.length}`);
  for (const tag of tags) {
    const name = /name="([^"]+)"/.exec(tag)?.[1] ?? tag.slice(0, 60);
    // `value={` + `onChange={` is what makes React the owner of the field. An
    // input with neither is reset by the form action; an input with only
    // `value=` is frozen and unusable.
    assert.match(tag, /value=\{/, `<input name="${name}"> must be controlled — an uncontrolled field is blanked by the form action`);
    assert.match(tag, /onChange=\{/, `<input name="${name}"> has a value but no onChange, which freezes it`);
    assert.ok(
      !/defaultValue=/.test(tag),
      `<input name="${name}"> uses defaultValue, which the form action still resets`,
    );
  }
