  // Capture the whole component body: the closing brace is a line that is
  // nothing but `}` (`\n}\n`). Anchoring on a bare `\n}` stopped at the closing
  // brace of the multi-line destructured props object (`}: { next?… } = {}) {`),
  // which sits at column 0 too — so the match ended before the body and every
  // assertion below saw an empty string. This is the very brittleness the
  // "Tolerates props" note warned about, now actually handled.
  const login = /export function LoginForm\([\s\S]*?\n}\n/.exec(AUTH_FORMS)?.[0] ?? "";
  assert.ok(login, "found LoginForm");
