  assert.equal(trustedClientIp(req({ "x-real-ip": "::ffff:127.0.0.1" })), "127.0.0.1");
  assert.equal(trustedClientIp(req({ "x-real-ip": "51.79.162.96:44321" })), "51.79.162.96");
  assert.equal(trustedClientIp(req({ "x-real-ip": "[2001:db8::1]" })), "2001:db8::1");
