/** Shape returned to the admin inbox client component. */
type InboxAttachment = { id: string; mime: string; sizeBytes: number } | null;
type InboxMessage = {
  id: string;
  sender: string;
  body: string;
  createdAt: string;
  attachment: InboxAttachment;
};
type InboxConversation = {
  id: string;
  visitorId: string;
  userId: string | null;
  name: string | null;
  email: string | null;
  status: string;
  assignedToId: string | null;
  /** Display name of the staff member handling it, resolved from assignedToId. */
  assignedToName: string | null;
  unreadForAgent: boolean;
  lastMessageAt: string;
  createdAt: string;
  /** True while the visitor is composing (transient, self-expiring). */
  visitorTyping: boolean;
  /** Staff-set kill switch for the AI assistant on this one thread (see `toggleAiPaused`). */
  aiPaused: boolean;
  messages: InboxMessage[];
};

/**
 * Resolve staff user ids to display names in one query. Not a "use server"
 * export (it takes non-serializable args and isn't called from the client);
 * used internally to attach `assignedToName` to inbox payloads so the admin
 * thread view can label each human reply with the agent handling it.
 */
async function resolveStaffNames(
  ids: (string | null)[]
): Promise<Map<string, string>> {
  const unique = Array.from(new Set(ids.filter((v): v is string => !!v)));
  if (unique.length === 0) return new Map();
  const users = await db.user.findMany({
    where: { id: { in: unique } },
    select: { id: true, name: true },
  });
  return new Map(users.map((u) => [u.id, u.name]));
}

/** List conversations for the inbox, unread + newest first. Polled by the client. */
export async function listConversations(): Promise<InboxConversation[]> {
  await requireGrant("liveChat");
  const rows = await db.chatConversation.findMany({
    orderBy: [{ unreadForAgent: "desc" }, { lastMessageAt: "desc" }],
    take: 200,
    include: { messages: { orderBy: { createdAt: "asc" }, include: { attachment: true } } },
  });
  const staffNames = await resolveStaffNames(rows.map((c) => c.assignedToId));
  return rows.map((c) => ({
    id: c.id,
    visitorId: c.visitorId,
    userId: c.userId,
    name: c.name,
    email: c.email,
    status: c.status,
    assignedToId: c.assignedToId,
    assignedToName: c.assignedToId ? staffNames.get(c.assignedToId) ?? null : null,
    unreadForAgent: c.unreadForAgent,
    lastMessageAt: c.lastMessageAt.toISOString(),
    createdAt: c.createdAt.toISOString(),
    visitorTyping: readTyping(c.id).visitor,
    aiPaused: c.aiPaused,
    messages: c.messages.map((m) => ({
      id: m.id,
      sender: m.sender,
      body: m.body,
      createdAt: m.createdAt.toISOString(),
      attachment: m.attachment
        ? { id: m.attachment.id, mime: m.attachment.mime, sizeBytes: m.attachment.sizeBytes }
        : null,
    })),
  }));
}

/** Fetch a single conversation's messages (used when opening / polling a thread). */
export async function getConversation(id: string): Promise<InboxConversation | null> {
  await requireGrant("liveChat");
  if (typeof id !== "string" || !id) return null;
  const c = await db.chatConversation.findUnique({
    where: { id },
    include: { messages: { orderBy: { createdAt: "asc" }, include: { attachment: true } } },
  });
  if (!c) return null;
  const staffNames = await resolveStaffNames([c.assignedToId]);
  return {
    id: c.id,
    visitorId: c.visitorId,
    userId: c.userId,
    name: c.name,
    email: c.email,
    status: c.status,
    assignedToId: c.assignedToId,
    assignedToName: c.assignedToId ? staffNames.get(c.assignedToId) ?? null : null,
    unreadForAgent: c.unreadForAgent,
    lastMessageAt: c.lastMessageAt.toISOString(),
    createdAt: c.createdAt.toISOString(),
    visitorTyping: readTyping(c.id).visitor,
    aiPaused: c.aiPaused,
    messages: c.messages.map((m) => ({
      id: m.id,
      sender: m.sender,
      body: m.body,
      createdAt: m.createdAt.toISOString(),
      attachment: m.attachment
        ? { id: m.attachment.id, mime: m.attachment.mime, sizeBytes: m.attachment.sizeBytes }
        : null,
    })),
  };
}

