"use server";

import { revalidatePath } from "next/cache";
import { db } from "@/lib/db";
import { requireArea } from "@/lib/rbac";
import { requireAdmin } from "@/lib/auth";
import { stripe, stripeConfigured } from "@/lib/stripe";

/**
 * Admin power-tools for finance ops: refunds, manual balance adjustments and
 * bulk invoice/client actions. Every action is gated by `requireArea("billing")`
 * (bulk-suspend is ADMIN-only, matching `adminSetUserSuspended`) and writes an
 * AuditLog row.
 *
 * The existing single-invoice void / mark-paid live in `lib/actions-billing.ts`
 * and are consumed directly from there (a "use server" file cannot re-export).
 */

async function audit(userId: string | null, action: string, detail?: string) {
  await db.auditLog.create({ data: { userId, action, detail } });
}

/**
 * Raised (and caught in the same function) when the compare-and-swap on an
 * invoice's `refundedCents` loses — i.e. another request already recorded this
 * refund step. Module-local, not an export: every EXPORT of a "use server" file
 * becomes a network-callable endpoint and must be an async function.
 */
class AlreadyRefundedError extends Error {}

