// Plain (non-"use server") module for values shared between the work-board
// server actions and the attachment routes — a "use server" file may only
// export async functions, so this constant lives here (same reason
// lib/board-shared.ts exists for the dev-ops Kanban).

/**
 * On-disk root for WORK-TASK attachments. Structurally identical to
 * BOARD_UPLOAD_DIR (lib/board-shared.ts) — same env-override-with-prod-default
 * shape — but a DELIBERATELY SEPARATE directory. The dev-ops board
 * (Board/Card/CardAttachment) and this staff task system (WorkBoard/WorkTask/
 * WorkTaskAttachment) are structurally separate model sets that must never
 * share storage, mirroring why they never share a Prisma model.
 */
export const WORK_UPLOAD_DIR = process.env.NXEON_WORK_UPLOAD_DIR ?? "/opt/nxeon/work-uploads";

"use server";

import { promises as fs } from "node:fs";
import { join } from "node:path";
import { revalidatePath } from "next/cache";
import type { CardPriority, Role, User } from "@prisma/client";
import { db } from "./db";
import { requireGrant } from "./staff-grants";
import { WORK_UPLOAD_DIR } from "./work-shared";

/**
 * Staff task/project management ("the ClickUp alternative"). Every export
 * gates on `requireGrant("tasks")` (SUPPORT/BILLING/ADMIN unconditionally per
 * AREA_ROLES.tasks in lib/rbac.ts; a Role.EMPLOYEE only with a StaffGrant).
 *
 * HARD SEPARATION FROM THE DEV-OPS BOARD: this file must never import
 * lib/actions-board.ts or reference the Card/Board models. That system is
 * requireAdmin()-gated everywhere and its card-movement hook spawns real
 * deploy/git scripts (publish-docs.mjs, deploy-staging.sh,
 * promote-production.sh) — see the Prisma schema's "WORK BOARDS" doc comment.
 * The Work* models here are a completely separate set precisely so this file
 * can be reachable by EMPLOYEE staff without any risk of reaching that.
 *
 * Every mutation calls the local `audit()` helper with an action string
 * starting "task." so /admin/tasks's Activity tab (a plain
 * `AuditLog.findMany({ where: { action: { startsWith: "task." } } })`) has
 * something real to show — the same pattern as lib/actions-admin-billing.ts's
 * own inline `audit()`. A shared, codebase-wide audit helper is a separate,
 * later piece of work (see lib/actions.ts's private `audit()` and the plan's
 * Phase 7) — this one is local to this file on purpose.
 */

async function audit(userId: string, action: string, detail?: string): Promise<void> {
  await db.auditLog.create({ data: { userId, action, detail } });
}

/** Where a task notification/activity link should point, so an EMPLOYEE never
 *  lands on the ADMIN-only shell and vice versa. */
function taskHref(role: Role, boardId: string, taskId: string): string {
  const base = role === "EMPLOYEE" ? "/staff/tasks" : "/admin/tasks";
  return `${base}?board=${boardId}&task=${taskId}`;
}

function refreshBoardPaths(): void {
  // Both portals render the same data from different routes; a mutation from
  // either side must be visible on both without a manual reload.
  revalidatePath("/admin/tasks");
  revalidatePath("/staff/tasks");
}

const PRIORITIES: CardPriority[] = ["LOW", "NORMAL", "HIGH", "URGENT"];
const DEFAULT_COLUMNS = ["To do", "In progress", "Done"];

// ---- Shared read shapes ------------------------------------------------

export type WorkBoardSummary = {
  id: string;
  name: string;
  description: string | null;
  taskCount: number;
  columnCount: number;
};

export type WorkTaskSummary = {
  id: string;
  title: string;
  priority: CardPriority;
  assigneeId: string | null;
  assigneeName: string | null;
  dueAt: string | null;
  position: number;
  completedAt: string | null;
  checklistTotal: number;
  checklistDone: number;
  commentCount: number;
  attachmentCount: number;
  updatedAt: string;
};

export type WorkColumnData = { id: string; name: string; position: number; tasks: WorkTaskSummary[] };
export type WorkBoardData = { id: string; name: string; description: string | null; columns: WorkColumnData[] };

export type WorkChecklistItemData = { id: string; label: string; done: boolean; position: number };
export type WorkCommentData = { id: string; authorId: string; authorName: string; body: string; createdAt: string };
export type WorkAttachmentData = {
  id: string;
  filename: string;
  kind: string;
  mime: string;
  sizeBytes: number;
  uploadedByName: string;
  url: string;
};

export type WorkTaskDetail = WorkTaskSummary & {
  description: string;
  boardId: string;
  columnId: string;
  columnName: string;
  checklist: WorkChecklistItemData[];
  comments: WorkCommentData[];
  attachments: WorkAttachmentData[];
};

export type AssignableUser = { id: string; name: string; email: string };

// ---- Boards --------------------------------------------------------------

/** Non-archived boards, oldest first, with lightweight counts for the picker. */
export async function listBoards(): Promise<WorkBoardSummary[]> {
  await requireGrant("tasks");
  const boards = await db.workBoard.findMany({
    where: { archivedAt: null },
    orderBy: { createdAt: "asc" },
    include: {
      _count: {
        select: { columns: true, tasks: { where: { archivedAt: null } } },
      },
    },
  });
  return boards.map((b) => ({
    id: b.id,
    name: b.name,
    description: b.description,
    taskCount: b._count.tasks,
    columnCount: b._count.columns,
  }));
}

export async function createBoard(name: string, description?: string): Promise<{ id?: string; error?: string }> {
  const actor = await requireGrant("tasks");
  const clean = String(name ?? "").trim().slice(0, 80);
  if (!clean) return { error: "Enter a board name." };
  const board = await db.workBoard.create({
    data: { name: clean, description: description?.trim().slice(0, 2000) || null, createdById: actor.id },
  });
  await db.workColumn.createMany({
    data: DEFAULT_COLUMNS.map((n, i) => ({ boardId: board.id, name: n, position: i })),
  });
  await audit(actor.id, "task.board.create", clean);
  refreshBoardPaths();
  return { id: board.id };
}

export async function renameBoard(id: string, name: string): Promise<{ error?: string }> {
  const actor = await requireGrant("tasks");
  const clean = String(name ?? "").trim().slice(0, 80);
  if (!clean) return { error: "Enter a board name." };
  await db.workBoard.update({ where: { id }, data: { name: clean } }).catch(() => undefined);
  await audit(actor.id, "task.board.rename", `${id} -> ${clean}`);
  refreshBoardPaths();
  return {};
}

/** Archive (soft-delete) a board — hides it from the picker, keeps the data. */
export async function archiveBoard(id: string): Promise<void> {
  const actor = await requireGrant("tasks");
  await db.workBoard.update({ where: { id }, data: { archivedAt: new Date() } }).catch(() => undefined);
  await audit(actor.id, "task.board.archive", id);
  refreshBoardPaths();
}

/** Full board with columns + task summaries (non-archived tasks only). */
export async function getBoard(boardId: string): Promise<WorkBoardData | null> {
  await requireGrant("tasks");
  const board = await db.workBoard.findFirst({
    where: { id: boardId, archivedAt: null },
    include: {
      columns: {
        orderBy: { position: "asc" },
        include: {
          tasks: {
            where: { archivedAt: null },
            orderBy: { position: "asc" },
            include: {
              assignee: { select: { id: true, name: true } },
              checklist: { select: { done: true } },
              _count: { select: { comments: true, attachments: true } },
            },
          },
        },
      },
    },
  });
  if (!board) return null;
  return {
    id: board.id,
    name: board.name,
    description: board.description,
    columns: board.columns.map((col) => ({
      id: col.id,
      name: col.name,
      position: col.position,
      tasks: col.tasks.map((t) => ({
        id: t.id,
        title: t.title,
        priority: t.priority,
        assigneeId: t.assigneeId,
        assigneeName: t.assignee?.name ?? null,
        dueAt: t.dueAt ? t.dueAt.toISOString() : null,
        position: t.position,
        completedAt: t.completedAt ? t.completedAt.toISOString() : null,
        checklistTotal: t.checklist.length,
        checklistDone: t.checklist.filter((c) => c.done).length,
        commentCount: t._count.comments,
        attachmentCount: t._count.attachments,
        updatedAt: t.updatedAt.toISOString(),
      })),
    })),
  };
}

/** Staff who can legitimately be assigned a task: everyone AREA_ROLES.tasks
 *  already lets in, plus any EMPLOYEE individually granted "tasks". Mirrors
 *  hasAreaAccess's own two-path logic (role fast-path OR StaffGrant lookup)
 *  so the picker never offers someone the assignment would silently 404 for. */
export async function listAssignableUsers(): Promise<AssignableUser[]> {
  await requireGrant("tasks");
  const users = await db.user.findMany({
    where: {
      OR: [
        { role: { in: ["SUPPORT", "BILLING", "ADMIN"] } },
        { role: "EMPLOYEE", staffGrants: { some: { area: "tasks" } } },
      ],
    },
    select: { id: true, name: true, email: true },
    orderBy: { name: "asc" },
  });
  return users;
}

// ---- Columns ---------------------------------------------------------------

export async function createColumn(boardId: string, name: string): Promise<{ error?: string }> {
  const actor = await requireGrant("tasks");
  const clean = String(name ?? "").trim().slice(0, 40);
  if (!clean) return { error: "Enter a column name." };
  const max = await db.workColumn.aggregate({ where: { boardId }, _max: { position: true } });
  await db.workColumn.create({ data: { boardId, name: clean, position: (max._max.position ?? -1) + 1 } });
  await audit(actor.id, "task.column.create", clean);
  refreshBoardPaths();
  return {};
}

export async function renameColumn(id: string, name: string): Promise<{ error?: string }> {
  const actor = await requireGrant("tasks");
  const clean = String(name ?? "").trim().slice(0, 40);
  if (!clean) return { error: "Enter a column name." };
  await db.workColumn.update({ where: { id }, data: { name: clean } }).catch(() => undefined);
  await audit(actor.id, "task.column.rename", `${id} -> ${clean}`);
  refreshBoardPaths();
  return {};
}

/** Reorder a column within its board; renumber siblings (full-list-renumber,
 *  same strategy as components/admin/BoardClient.tsx's moveColumn). */
export async function moveColumn(columnId: string, toIndex: number): Promise<void> {
  const actor = await requireGrant("tasks");
  const col = await db.workColumn.findUnique({ where: { id: columnId }, select: { boardId: true } });
  if (!col) return;
  const siblings = await db.workColumn.findMany({
    where: { boardId: col.boardId, NOT: { id: columnId } },
    orderBy: { position: "asc" },
    select: { id: true },
  });
  const order = siblings.map((s) => s.id);
  const idx = Math.max(0, Math.min(toIndex, order.length));
  order.splice(idx, 0, columnId);
  await db.$transaction(order.map((id, i) => db.workColumn.update({ where: { id }, data: { position: i } })));
  await audit(actor.id, "task.column.move", columnId);
  refreshBoardPaths();
}

// ---- Tasks ------------------------------------------------------------

export async function createTask(columnId: string, title: string): Promise<{ id?: string; error?: string }> {
  const actor = await requireGrant("tasks");
  const col = await db.workColumn.findUnique({ where: { id: columnId }, select: { boardId: true } });
  if (!col) return { error: "Column not found." };
  const clean = String(title ?? "").trim().slice(0, 200);
  if (!clean) return { error: "Enter a title." };
  const max = await db.workTask.aggregate({ where: { columnId }, _max: { position: true } });
  const task = await db.workTask.create({
    data: {
      boardId: col.boardId,
      columnId,
      title: clean,
      position: (max._max.position ?? -1) + 1,
      createdById: actor.id,
    },
  });
  await audit(actor.id, "task.create", clean);
  refreshBoardPaths();
  return { id: task.id };
}

/** Full task detail (checklist + comments + attachments + assignee/board context). */
export async function getTask(taskId: string): Promise<WorkTaskDetail | null> {
  await requireGrant("tasks");
  const t = await db.workTask.findUnique({
    where: { id: taskId },
    include: {
      assignee: { select: { id: true, name: true } },
      column: { select: { name: true } },
      checklist: { orderBy: { position: "asc" } },
      comments: { orderBy: { createdAt: "asc" }, include: { author: { select: { name: true } } } },
      attachments: { orderBy: { createdAt: "asc" }, include: { uploadedBy: { select: { name: true } } } },
    },
  });
  if (!t) return null;
  return {
    id: t.id,
    title: t.title,
    description: t.description,
    priority: t.priority,
    assigneeId: t.assigneeId,
    assigneeName: t.assignee?.name ?? null,
    dueAt: t.dueAt ? t.dueAt.toISOString() : null,
    position: t.position,
    completedAt: t.completedAt ? t.completedAt.toISOString() : null,
    boardId: t.boardId,
    columnId: t.columnId,
    columnName: t.column.name,
    checklistTotal: t.checklist.length,
    checklistDone: t.checklist.filter((c) => c.done).length,
    commentCount: t.comments.length,
    attachmentCount: t.attachments.length,
    updatedAt: t.updatedAt.toISOString(),
    checklist: t.checklist.map((c) => ({ id: c.id, label: c.label, done: c.done, position: c.position })),
    comments: t.comments.map((c) => ({
      id: c.id,
      authorId: c.authorId,
      authorName: c.author.name,
      body: c.body,
      createdAt: c.createdAt.toISOString(),
    })),
    attachments: t.attachments.map((a) => ({
      id: a.id,
      filename: a.filename,
      kind: a.kind,
      mime: a.mime,
      sizeBytes: a.sizeBytes,
      uploadedByName: a.uploadedBy.name,
      url: `/api/work/attachments/${a.id}`,
    })),
  };
}

/** Edit a task's title and/or description. Not part of the original "one verb
 *  per mutation" list but genuinely required for this to be a real task tool —
 *  the schema's `description` field would otherwise be permanently unreachable. */
export async function updateTask(taskId: string, patch: { title?: string; description?: string }): Promise<{ error?: string }> {
  const actor = await requireGrant("tasks");
  const data: Record<string, string> = {};
  if (patch.title !== undefined) {
    const t = patch.title.trim().slice(0, 200);
    if (!t) return { error: "Title can't be empty." };
    data.title = t;
  }
  if (patch.description !== undefined) data.description = patch.description.slice(0, 20_000);
  if (Object.keys(data).length === 0) return {};
  await db.workTask.update({ where: { id: taskId }, data }).catch(() => undefined);
  await audit(actor.id, "task.update", taskId);
  refreshBoardPaths();
  return {};
}

/** Move a task to a column at a position; renumber siblings (full-list-renumber,
 *  same strategy as lib/actions-board.ts's moveCard — dnd-kit drives the drag
 *  gesture, this is the same server-side reorder). */
export async function moveTask(taskId: string, toColumnId: string, toIndex: number): Promise<void> {
  const actor = await requireGrant("tasks");
  const task = await db.workTask.findUnique({ where: { id: taskId }, select: { columnId: true, boardId: true } });
  const col = await db.workColumn.findUnique({ where: { id: toColumnId }, select: { boardId: true } });
  if (!task || !col || col.boardId !== task.boardId) return;
  const siblings = await db.workTask.findMany({
    where: { columnId: toColumnId, archivedAt: null, NOT: { id: taskId } },
    orderBy: { position: "asc" },
    select: { id: true },
  });
  const order = siblings.map((s) => s.id);
  const idx = Math.max(0, Math.min(toIndex, order.length));
  order.splice(idx, 0, taskId);
  await db.$transaction([
    db.workTask.update({ where: { id: taskId }, data: { columnId: toColumnId } }),
    ...order.map((id, i) => db.workTask.update({ where: { id }, data: { position: i } })),
  ]);
  await audit(actor.id, "task.move", `${taskId} -> column ${toColumnId}`);
  refreshBoardPaths();
}

/** Assign (or unassign with null) a task. Notifies the new assignee — never
 *  the actor themself (self-assignment is not news). */
export async function assignTask(taskId: string, assigneeId: string | null): Promise<{ error?: string }> {
  const actor = await requireGrant("tasks");
  const task = await db.workTask.findUnique({ where: { id: taskId }, select: { boardId: true, title: true } });
  if (!task) return { error: "Task not found." };
  if (assigneeId) {
    const assignee = await db.user.findUnique({ where: { id: assigneeId }, select: { id: true, role: true } });
    if (!assignee) return { error: "User not found." };
    await db.workTask.update({ where: { id: taskId }, data: { assigneeId } });
    if (assigneeId !== actor.id) {
      await db.notification.create({
        data: {
          userId: assigneeId,
          title: `You were assigned: ${task.title}`,
          href: taskHref(assignee.role, task.boardId, taskId),
        },
      });
    }
  } else {
    await db.workTask.update({ where: { id: taskId }, data: { assigneeId: null } });
  }
  await audit(actor.id, "task.assign", `${taskId} -> ${assigneeId ?? "unassigned"}`);
  refreshBoardPaths();
  return {};
}

export async function setTaskPriority(taskId: string, priority: CardPriority): Promise<{ error?: string }> {
  const actor = await requireGrant("tasks");
  if (!PRIORITIES.includes(priority)) return { error: "Invalid priority." };
  await db.workTask.update({ where: { id: taskId }, data: { priority } }).catch(() => undefined);
  await audit(actor.id, "task.priority", `${taskId} -> ${priority}`);
  refreshBoardPaths();
  return {};
}

/** `dueAt: null` clears the due date; otherwise an ISO date/datetime string. */
export async function setTaskDueDate(taskId: string, dueAt: string | null): Promise<{ error?: string }> {
  const actor = await requireGrant("tasks");
  let parsed: Date | null = null;
  if (dueAt) {
    parsed = new Date(dueAt);
    if (Number.isNaN(parsed.getTime())) return { error: "Invalid date." };
  }
  await db.workTask.update({ where: { id: taskId }, data: { dueAt: parsed } }).catch(() => undefined);
  await audit(actor.id, "task.due", `${taskId} -> ${parsed ? parsed.toISOString() : "cleared"}`);
  refreshBoardPaths();
  return {};
}

/** Toggle a task's done state (`completedAt` set/cleared). */
export async function completeTask(taskId: string, completed: boolean): Promise<void> {
  const actor = await requireGrant("tasks");
  await db.workTask
    .update({ where: { id: taskId }, data: { completedAt: completed ? new Date() : null } })
    .catch(() => undefined);
  await audit(actor.id, completed ? "task.complete" : "task.reopen", taskId);
  refreshBoardPaths();
}

/** Archive (soft-delete) a task — hides it from the board, keeps checklist/
 *  comments/attachments and the audit trail intact. */
export async function archiveTask(taskId: string): Promise<void> {
  const actor = await requireGrant("tasks");
  await db.workTask.update({ where: { id: taskId }, data: { archivedAt: new Date() } }).catch(() => undefined);
  await audit(actor.id, "task.archive", taskId);
  refreshBoardPaths();
}

// ---- Checklist ---------------------------------------------------------

export async function addChecklistItem(taskId: string, label: string): Promise<{ id?: string; error?: string }> {
  const actor = await requireGrant("tasks");
  const clean = String(label ?? "").trim().slice(0, 200);
  if (!clean) return { error: "Enter a checklist item." };
  const max = await db.workChecklistItem.aggregate({ where: { taskId }, _max: { position: true } });
  const item = await db.workChecklistItem.create({
    data: { taskId, label: clean, position: (max._max.position ?? -1) + 1 },
  });
  await audit(actor.id, "task.checklist.add", `${taskId}: ${clean}`);
  refreshBoardPaths();
  return { id: item.id };
}

export async function toggleChecklistItem(id: string, done: boolean): Promise<void> {
  const actor = await requireGrant("tasks");
  const item = await db.workChecklistItem.update({ where: { id }, data: { done } }).catch(() => null);
  await audit(actor.id, "task.checklist.toggle", `${item?.taskId ?? id} -> ${done}`);
  refreshBoardPaths();
}

export async function deleteChecklistItem(id: string): Promise<void> {
  const actor = await requireGrant("tasks");
  const item = await db.workChecklistItem.delete({ where: { id } }).catch(() => null);
  await audit(actor.id, "task.checklist.delete", item?.taskId ?? id);
  refreshBoardPaths();
}

// ---- Comments ---------------------------------------------------------

/** Add a comment, attributed to the real signed-in author. Notifies the
 *  task's assignee (if any, and if they aren't the one commenting). */
export async function addComment(taskId: string, body: string): Promise<{ id?: string; error?: string }> {
  const actor = await requireGrant("tasks");
  const clean = String(body ?? "").trim().slice(0, 5000);
  if (!clean) return { error: "Write something." };
  const task = await db.workTask.findUnique({
    where: { id: taskId },
    select: { boardId: true, title: true, assigneeId: true, assignee: { select: { role: true } } },
  });
  if (!task) return { error: "Task not found." };
  const comment = await db.workTaskComment.create({ data: { taskId, authorId: actor.id, body: clean } });
  if (task.assigneeId && task.assigneeId !== actor.id && task.assignee) {
    await db.notification.create({
      data: {
        userId: task.assigneeId,
        title: `New comment on: ${task.title}`,
        href: taskHref(task.assignee.role, task.boardId, taskId),
      },
    });
  }
  await audit(actor.id, "task.comment.add", `${taskId}`);
  refreshBoardPaths();
  return { id: comment.id };
}

export async function deleteComment(id: string): Promise<{ error?: string }> {
  const actor = await requireGrant("tasks");
  const comment = await db.workTaskComment.findUnique({ where: { id }, select: { authorId: true, taskId: true } });
  if (!comment) return {};
  // A comment's own author (or an ADMIN) may remove it — everyone else with the
  // "tasks" grant can read/write tasks, but shouldn't get to delete someone
  // else's remark just because they also hold the grant.
  if (comment.authorId !== actor.id && actor.role !== "ADMIN") return { error: "You can only delete your own comments." };
  await db.workTaskComment.delete({ where: { id } }).catch(() => undefined);
  await audit(actor.id, "task.comment.delete", comment.taskId);
  refreshBoardPaths();
  return {};
}

// ---- Attachments ------------------------------------------------------
// Upload is handled by app/api/work/attachments/route.ts (a "use server" file
// can't accept a multipart FormData upload as cleanly as a route handler, and
// this mirrors app/api/board/attachments/route.ts's own split). Deletion is a
// plain action since it only needs an id.

export async function deleteAttachment(id: string): Promise<{ error?: string }> {
  const actor = await requireGrant("tasks");
  const att = await db.workTaskAttachment.findUnique({ where: { id } });
  if (!att) return {};
  if (att.uploadedById !== actor.id && actor.role !== "ADMIN") {
    return { error: "You can only delete your own attachments." };
  }
  await db.workTaskAttachment.delete({ where: { id } }).catch(() => undefined);
  await fs.rm(join(WORK_UPLOAD_DIR, att.taskId, att.storedName), { force: true }).catch(() => undefined);
  await audit(actor.id, "task.attachment.delete", att.taskId);
  refreshBoardPaths();
  return {};
}

import { NextRequest, NextResponse } from "next/server";
import { promises as fs } from "node:fs";
import { join } from "node:path";
import { randomBytes } from "node:crypto";
import { requireGrant } from "@/lib/staff-grants";
import { db } from "@/lib/db";
import { WORK_UPLOAD_DIR } from "@/lib/work-shared";
import { isAllowedImageMime, sniffImageMime } from "@/lib/chat-attachment";

// Videos can be large; everything else is capped tighter. Same caps as the
// dev-ops board's own upload route (app/api/board/attachments/route.ts) — no
// reason for a staff task attachment to have a different budget.
const MAX_VIDEO = 300 * 1024 * 1024;
const MAX_OTHER = 50 * 1024 * 1024;

function kindFor(mime: string): "IMAGE" | "VIDEO" | "FILE" {
  if (mime.startsWith("image/")) return "IMAGE";
  if (mime.startsWith("video/")) return "VIDEO";
  return "FILE";
}

/** Upload an attachment to a work task. Gated on the "tasks" grant — reachable
 *  by a Role.EMPLOYEE with that grant, not just admin staff. `?taskId=` in the
 *  query. Stored on disk under WORK_UPLOAD_DIR (never board-uploads/ — see
 *  lib/work-shared.ts). */
export async function POST(req: NextRequest) {
  let actor;
  try {
    actor = await requireGrant("tasks");
  } catch {
    return NextResponse.json({ error: "Forbidden" }, { status: 403 });
  }
  const taskId = req.nextUrl.searchParams.get("taskId") ?? "";
  const task = await db.workTask.findUnique({ where: { id: taskId }, select: { id: true } });
  if (!task) return NextResponse.json({ error: "Task not found" }, { status: 404 });

  const form = await req.formData();
  const file = form.get("file");
  if (!(file instanceof File)) return NextResponse.json({ error: "No file" }, { status: 400 });

  let mime = file.type || "application/octet-stream";
  let kind = kindFor(mime);
  const cap = kind === "VIDEO" ? MAX_VIDEO : MAX_OTHER;
  if (file.size > cap) return NextResponse.json({ error: `File too large (max ${Math.round(cap / 1024 / 1024)} MB)` }, { status: 413 });

  const buf = Buffer.from(await file.arrayBuffer());

  // A file that CLAIMS to be an image is served inline by the [id] route, so it
  // must be a real raster image — never a scripted SVG (stored XSS in the
  // portal origin). Verify by byte signature; SVG has no signature and isn't
  // allow-listed, so it's rejected here (same reasoning as the board's route).
  if (kind === "IMAGE") {
    const sniffed = sniffImageMime(buf);
    if (!sniffed || mime === "image/svg+xml" || !isAllowedImageMime(mime)) {
      return NextResponse.json({ error: "Only PNG, JPEG, GIF, or WEBP images are allowed." }, { status: 400 });
    }
    mime = sniffed;
    kind = kindFor(mime);
  }

  const ext = (file.name.match(/\.[A-Za-z0-9]{1,8}$/)?.[0] ?? "").toLowerCase();
  const storedName = `${randomBytes(12).toString("hex")}${ext}`;
  const dir = join(WORK_UPLOAD_DIR, taskId);
  try {
    await fs.mkdir(dir, { recursive: true });
    await fs.writeFile(join(dir, storedName), buf);
  } catch (e) {
    console.error("[work] attachment write failed:", e);
    return NextResponse.json(
      { error: `Couldn't save the file (${(e as NodeJS.ErrnoException)?.code ?? "write error"}). Ensure ${WORK_UPLOAD_DIR} is writable by the web user.` },
      { status: 500 },
    );
  }

  const att = await db.workTaskAttachment.create({
    data: { taskId, filename: file.name.slice(0, 200), storedName, mime, sizeBytes: file.size, kind, uploadedById: actor.id },
  });
  await db.auditLog.create({ data: { userId: actor.id, action: "task.attachment.add", detail: `${taskId}: ${att.filename}` } });
  return NextResponse.json({ id: att.id, filename: att.filename, kind, mime, sizeBytes: att.sizeBytes, url: `/api/work/attachments/${att.id}` });
}

import { NextRequest, NextResponse } from "next/server";
import { createReadStream } from "node:fs";
import { promises as fs } from "node:fs";
import { join } from "node:path";
import { Readable } from "node:stream";
import { requireGrant } from "@/lib/staff-grants";
import { db } from "@/lib/db";
import { WORK_UPLOAD_DIR } from "@/lib/work-shared";

/** Stream a work-task attachment. Gated on the "tasks" grant (same authority
 *  as every action in lib/actions-work.ts) — mirrors
 *  app/api/board/attachments/[id]/route.ts's serving logic, re-gated for this
 *  separate, EMPLOYEE-reachable system. Supports Range so video seeks work. */
export async function GET(req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  try {
    await requireGrant("tasks");
  } catch {
    return new NextResponse("Forbidden", { status: 403 });
  }
  const { id } = await params;
  const att = await db.workTaskAttachment.findUnique({ where: { id } });
  if (!att) return new NextResponse("Not found", { status: 404 });
  const path = join(WORK_UPLOAD_DIR, att.taskId, att.storedName);
  let size: number;
  try {
    size = (await fs.stat(path)).size;
  } catch {
    return new NextResponse("Missing", { status: 404 });
  }

  const range = req.headers.get("range");
  const disposition = att.kind === "FILE" ? `attachment; filename="${att.filename.replace(/"/g, "")}"` : "inline";
  // Never let an inline-served attachment execute as a document: `nosniff` stops
  // MIME-sniffing an image into HTML, and `default-src 'none'; sandbox` neuters
  // any script even in a legacy SVG that predates the upload-side reject.
  const baseHeaders: Record<string, string> = {
    "Content-Type": att.mime,
    "Content-Disposition": disposition,
    "Accept-Ranges": "bytes",
    "X-Content-Type-Options": "nosniff",
    "Content-Security-Policy": "default-src 'none'; sandbox",
  };

  if (range) {
    const m = /bytes=(\d+)-(\d*)/.exec(range);
    if (m) {
      const start = Number(m[1]);
      const end = m[2] ? Math.min(Number(m[2]), size - 1) : size - 1;
      if (start <= end && start < size) {
        const stream = createReadStream(path, { start, end });
        return new NextResponse(Readable.toWeb(stream) as unknown as ReadableStream, {
          status: 206,
          headers: { ...baseHeaders, "Content-Range": `bytes ${start}-${end}/${size}`, "Content-Length": String(end - start + 1) },
        });
      }
    }
  }
  const stream = createReadStream(path);
  return new NextResponse(Readable.toWeb(stream) as unknown as ReadableStream, {
    status: 200,
    headers: { ...baseHeaders, "Content-Length": String(size) },
  });
}

