const PRIORITY_DOT: Record<string, string> = { LOW: "bg-slate-500", NORMAL: "bg-sky-400", HIGH: "bg-amber-400", URGENT: "bg-red-400" };
const PRIORITIES = ["LOW", "NORMAL", "HIGH", "URGENT"];

function relativeTime(iso: string): string {
  const then = new Date(iso).getTime();
  const s = Math.max(0, Math.floor((Date.now() - then) / 1000));
  if (s < 60) return "just now";
  const m = Math.floor(s / 60);
  if (m < 60) return `${m}m ago`;
  const h = Math.floor(m / 60);
  if (h < 24) return `${h}h ago`;
  const d = Math.floor(h / 24);
  if (d < 30) return `${d}d ago`;
  return new Date(iso).toLocaleDateString();
}

function isOverdue(task: WorkTaskSummary): boolean {
  return !task.completedAt && !!task.dueAt && new Date(task.dueAt).getTime() < Date.now();
}

/**
 * The Kanban board: columns + drag-and-drop task cards (dnd-kit) + a task
 * detail panel. Rendered identically under /admin/tasks and /staff/tasks —
 * the only difference between the two portals is which gate got the user
 * here (lib/staff-grants.ts's requireAreaOrGrant) and which base path task
 * notifications link back to.
 */
export function WorkBoardClient({
  board,
  portal,
  assignableUsers,
  initialTaskId,
}: {
  board: WorkBoardData;
  portal: "admin" | "staff";
  assignableUsers: AssignableUser[];
  initialTaskId?: string | null;
}) {
  const router = useRouter();
  const [cols, setCols] = useState<WorkColumnData[]>(board.columns);
  useEffect(() => setCols(board.columns), [board]);
  const [openTaskId, setOpenTaskId] = useState<string | null>(initialTaskId ?? null);
  const [activeId, setActiveId] = useState<string | null>(null);
  const [addingCol, setAddingCol] = useState<string | null>(null);

  const sensors = useSensors(useSensor(PointerSensor, { activationConstraint: { distance: 5 } }));

  function findColumnOfTask(taskId: string): WorkColumnData | undefined {
    return cols.find((c) => c.tasks.some((t) => t.id === taskId));
  }
  function findTask(taskId: string): WorkTaskSummary | undefined {
    for (const c of cols) {
      const t = c.tasks.find((x) => x.id === taskId);
      if (t) return t;
    }
    return undefined;
  }

  function onDragStart(e: DragStartEvent) {
    setActiveId(String(e.active.id));
  }

  // Full-list-renumber-on-drop, same strategy as components/admin/BoardClient's
  // moveCard: figure out the destination column + index, splice the task in
  // locally for instant feedback, then let the server renumber positions
  // 0..n in a transaction (lib/actions-work.ts's moveTask).
  async function onDragEnd(e: DragEndEvent) {
    const { active, over } = e;
    setActiveId(null);
    if (!over) return;
    const taskId = String(active.id);
    const sourceCol = findColumnOfTask(taskId);
    if (!sourceCol) return;

    let targetColId: string;
    let targetIndex: number;
    const overData = over.data.current as { type?: string; columnId?: string } | undefined;
    if (overData?.type === "column") {
      targetColId = overData.columnId!;
      const targetCol = cols.find((c) => c.id === targetColId);
      targetIndex = targetCol ? targetCol.tasks.filter((t) => t.id !== taskId).length : 0;
    } else {
      const overTaskId = String(over.id);
      const targetCol = findColumnOfTask(overTaskId);
      if (!targetCol) return;
      targetColId = targetCol.id;
      const rawIndex = targetCol.tasks.findIndex((t) => t.id === overTaskId);
      targetIndex = rawIndex < 0 ? targetCol.tasks.length : rawIndex;
    }
    const currentIndex = sourceCol.tasks.findIndex((t) => t.id === taskId);
    if (targetColId === sourceCol.id && targetIndex === currentIndex) return;

    setCols((prev) => {
      let moved: WorkTaskSummary | undefined;
      const stripped = prev.map((c) => ({
        ...c,
        tasks: c.tasks.filter((t) => (t.id === taskId ? ((moved = t), false) : true)),
      }));
      if (!moved) return prev;
      return stripped.map((c) =>
        c.id === targetColId ? { ...c, tasks: [...c.tasks.slice(0, targetIndex), moved!, ...c.tasks.slice(targetIndex)] } : c,
      );
    });
    await moveTask(taskId, targetColId, targetIndex);
    router.refresh();
  }

  async function moveColLeft(colId: string) {
    const idx = cols.findIndex((c) => c.id === colId);
    if (idx <= 0) return;
    setCols((prev) => {
      const next = [...prev];
      [next[idx - 1], next[idx]] = [next[idx], next[idx - 1]];
      return next;
    });
    await moveColumn(colId, idx - 1);
    router.refresh();
  }
  async function moveColRight(colId: string) {
    const idx = cols.findIndex((c) => c.id === colId);
    if (idx < 0 || idx >= cols.length - 1) return;
    setCols((prev) => {
      const next = [...prev];
      [next[idx], next[idx + 1]] = [next[idx + 1], next[idx]];
      return next;
    });
    await moveColumn(colId, idx + 1);
    router.refresh();
  }

  const activeTask = activeId ? findTask(activeId) : undefined;

  return (
    <div className="flex flex-1 flex-col gap-2 overflow-hidden">
      <DndContext sensors={sensors} collisionDetection={closestCorners} onDragStart={onDragStart} onDragEnd={onDragEnd}>
        <div className="flex flex-1 gap-3 overflow-x-auto pb-2">
          {cols.map((col, i) => (
            <Column
              key={col.id}
              col={col}
              isFirst={i === 0}
              isLast={i === cols.length - 1}
              onOpenTask={setOpenTaskId}
              onRefresh={() => router.refresh()}
              onMoveLeft={() => moveColLeft(col.id)}
              onMoveRight={() => moveColRight(col.id)}
              adding={addingCol === col.id}
              onStartAdd={() => setAddingCol(col.id)}
              onCancelAdd={() => setAddingCol(null)}
            />
          ))}
          <NewColumn boardId={board.id} onDone={() => router.refresh()} />
        </div>
        {typeof document !== "undefined" &&
          createPortal(<DragOverlay>{activeTask ? <TaskCardBody task={activeTask} /> : null}</DragOverlay>, document.body)}
      </DndContext>

      {openTaskId && (
        <TaskModal
          taskId={openTaskId}
          onClose={() => setOpenTaskId(null)}
          assignableUsers={assignableUsers}
          onChanged={() => router.refresh()}
        />
      )}
    </div>
  );
}

function Column({
  col,
  isFirst,
  isLast,
  onOpenTask,
  onRefresh,
  onMoveLeft,
  onMoveRight,
  adding,
  onStartAdd,
  onCancelAdd,
}: {
  col: WorkColumnData;
  isFirst: boolean;
  isLast: boolean;
  onOpenTask: (id: string) => void;
  onRefresh: () => void;
  onMoveLeft: () => void;
  onMoveRight: () => void;
  adding: boolean;
  onStartAdd: () => void;
  onCancelAdd: () => void;
}) {
  const { setNodeRef, isOver } = useDroppable({ id: `col:${col.id}`, data: { type: "column", columnId: col.id } });
  const [editingName, setEditingName] = useState(false);
  const [name, setName] = useState(col.name);
  const [title, setTitle] = useState("");
  useEffect(() => setName(col.name), [col.name]);

  async function saveName() {
    setEditingName(false);
    if (name.trim() && name.trim() !== col.name) {
      await renameColumn(col.id, name.trim());
      onRefresh();
    } else setName(col.name);
  }

  async function add() {
    if (!title.trim()) return;
    await createTask(col.id, title.trim());
    setTitle("");
    onCancelAdd();
    onRefresh();
  }

  return (
    <div className="flex h-full w-64 shrink-0 flex-col rounded-xl border border-white/[0.06] bg-white/[0.02]">
      <div className="flex flex-shrink-0 items-center justify-between gap-1 px-3 py-2">
        {editingName ? (
          <input
            autoFocus
            className="input py-0.5 text-sm"
            value={name}
            onChange={(e) => setName(e.target.value)}
            onBlur={saveName}
            onKeyDown={(e) => {
              if (e.key === "Enter") saveName();
              if (e.key === "Escape") {
                setName(col.name);
                setEditingName(false);
              }
            }}
          />
        ) : (
          <span className="select-none text-sm font-medium text-slate-300" onDoubleClick={() => setEditingName(true)} title="Double-click to rename">
            {col.name}
          </span>
        )}
        <span className="flex items-center gap-1">
          <button disabled={isFirst} onClick={onMoveLeft} className="text-xs text-slate-600 hover:text-slate-300 disabled:opacity-20" title="Move stage left">
            &#8592;
          </button>
          <span className="text-xs text-slate-500">{col.tasks.length}</span>
          <button disabled={isLast} onClick={onMoveRight} className="text-xs text-slate-600 hover:text-slate-300 disabled:opacity-20" title="Move stage right">
            &#8594;
          </button>
        </span>
      </div>
      <div ref={setNodeRef} className={`flex-1 space-y-2 overflow-y-auto px-2 pb-2 ${isOver ? "bg-brand-500/5" : ""}`}>
        <SortableContext items={col.tasks.map((t) => t.id)} strategy={verticalListSortingStrategy}>
          {col.tasks.map((task) => (
            <TaskCard key={task.id} task={task} onOpen={() => onOpenTask(task.id)} />
          ))}
        </SortableContext>
      </div>
      {adding ? (
        <div className="p-2">
          <textarea
            autoFocus
            className="input text-sm"
            rows={2}
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            placeholder="Task title…"
            onKeyDown={(e) => {
              if (e.key === "Enter" && !e.shiftKey) {
                e.preventDefault();
                add();
              }
              if (e.key === "Escape") onCancelAdd();
            }}
          />
          <div className="mt-1 flex gap-2">
            <button className="btn-primary text-xs" onClick={add}>Add</button>
            <button className="btn-secondary text-xs" onClick={onCancelAdd}>Cancel</button>
          </div>
        </div>
      ) : (
        <button className="px-3 py-2 text-left text-xs text-slate-500 hover:text-slate-300" onClick={onStartAdd}>
          + Add task
        </button>
      )}
    </div>
  );
}

function TaskCardBody({ task }: { task: WorkTaskSummary }) {
  return (
    <div className="w-60 cursor-grabbing rounded-lg border border-white/15 bg-navy-850 p-2.5 shadow-2xl">
      <div className="mb-1 flex items-center gap-1.5">
        <span className={`h-2 w-2 rounded-full ${PRIORITY_DOT[task.priority]}`} title={task.priority} />
        {task.completedAt && <span className="text-[10px] font-medium text-emerald-400">done</span>}
      </div>
      <p className={`text-sm ${task.completedAt ? "text-slate-500 line-through" : "text-slate-200"}`}>{task.title}</p>
    </div>
  );
}

function TaskCard({ task, onOpen }: { task: WorkTaskSummary; onOpen: () => void }) {
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({ id: task.id });
  const style = { transform: CSS.Transform.toString(transform), transition, opacity: isDragging ? 0.35 : 1 };
  return (
    <div
      ref={setNodeRef}
      style={style}
      {...attributes}
      {...listeners}
      onClick={onOpen}
      className="cursor-pointer rounded-lg border border-white/[0.06] bg-navy-850/80 p-2.5 hover:border-white/15"
    >
      <div className="mb-1 flex items-center gap-1.5">
        <span className={`h-2 w-2 rounded-full ${PRIORITY_DOT[task.priority]}`} title={task.priority} />
        {task.completedAt && <span className="text-[10px] font-medium text-emerald-400">done</span>}
        {isOverdue(task) && <span className="text-[10px] font-medium text-red-400">overdue</span>}
      </div>
      <p className={`text-sm ${task.completedAt ? "text-slate-500 line-through" : "text-slate-200"}`}>{task.title}</p>
      {task.checklistTotal > 0 && (
        <div className="mt-1 h-1 w-full overflow-hidden rounded-full bg-white/[0.06]">
          <div
            className="h-full rounded-full bg-brand-400"
            style={{ width: `${Math.round((task.checklistDone / task.checklistTotal) * 100)}%` }}
          />
        </div>
      )}
      <div className="mt-1.5 flex items-center gap-2 text-[11px] text-slate-500">
        {task.assigneeName && <span>@{task.assigneeName}</span>}
        {task.dueAt && <span className={isOverdue(task) ? "text-red-400" : ""}>{new Date(task.dueAt).toLocaleDateString()}</span>}
        {task.attachmentCount > 0 && <span>📎 {task.attachmentCount}</span>}
        {task.commentCount > 0 && <span>💬 {task.commentCount}</span>}
        {task.checklistTotal > 0 && <span>☑ {task.checklistDone}/{task.checklistTotal}</span>}
        <span className="ml-auto" title={new Date(task.updatedAt).toLocaleString()}>{relativeTime(task.updatedAt)}</span>
      </div>
    </div>
  );
}

function NewColumn({ boardId, onDone }: { boardId: string; onDone: () => void }) {
  const [name, setName] = useState("");
  return (
    <div className="w-56 shrink-0">
      <div className="flex items-center gap-2 rounded-xl border border-dashed border-white/10 p-2">
        <input
          className="input text-sm"
          placeholder="+ New stage"
          value={name}
          onChange={(e) => setName(e.target.value)}
          onKeyDown={async (e) => {
            if (e.key === "Enter" && name.trim()) {
              await createColumn(boardId, name.trim());
              setName("");
              onDone();
            }
          }}
        />
      </div>
    </div>
  );
}

function TaskModal({
  taskId,
  onClose,
  assignableUsers,
  onChanged,
}: {
  taskId: string;
  onClose: () => void;
  assignableUsers: AssignableUser[];
  onChanged: () => void;
}) {
  const [task, setTask] = useState<WorkTaskDetail | null>(null);
  const [desc, setDesc] = useState("");
  const [checklistLabel, setChecklistLabel] = useState("");
  const [comment, setComment] = useState("");
  const [uploading, setUploading] = useState(false);
  const fileRef = useRef<HTMLInputElement>(null);

  async function load() {
    const t = await getTask(taskId);
    setTask(t);
    if (t) setDesc(t.description);
  }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  useEffect(() => { load(); }, [taskId]);

  if (!task) return null;

  async function saveTitle(v: string) {
    if (v.trim() && v.trim() !== task!.title) {
      await updateTask(taskId, { title: v.trim() });
      await load();
      onChanged();
    }
  }
  async function saveDescription() {
    if (desc !== task!.description) {
      await updateTask(taskId, { description: desc });
      await load();
      onChanged();
    }
  }
  async function onPriorityChange(p: string) {
    await setTaskPriority(taskId, p as WorkTaskDetail["priority"]);
    await load();
    onChanged();
  }
  async function onAssigneeChange(id: string) {
    await assignTask(taskId, id || null);
    await load();
    onChanged();
  }
  async function onDueChange(v: string) {
    await setTaskDueDate(taskId, v || null);
    await load();
    onChanged();
  }
  async function onToggleComplete() {
    await completeTask(taskId, !task!.completedAt);
    await load();
    onChanged();
  }
  async function onArchive() {
    if (confirm("Archive this task? (hides it, keeps its checklist/comments/attachments)")) {
      await archiveTask(taskId);
      onChanged();
      onClose();
    }
  }

  async function addItem() {
    if (!checklistLabel.trim()) return;
    await addChecklistItem(taskId, checklistLabel.trim());
    setChecklistLabel("");
    await load();
    onChanged();
  }
  async function toggleItem(id: string, done: boolean) {
    await toggleChecklistItem(id, done);
    await load();
    onChanged();
  }
  async function removeItem(id: string) {
    await deleteChecklistItem(id);
    await load();
    onChanged();
  }

  async function postComment() {
    if (!comment.trim()) return;
    await addComment(taskId, comment.trim());
    setComment("");
    await load();
    onChanged();
  }
  async function removeComment(id: string) {
    const res = await deleteComment(id);
    if (res.error) { alert(res.error); return; }
    await load();
    onChanged();
  }

  async function uploadFiles(files: File[]) {
    if (!files.length) return;
    setUploading(true);
    for (const f of files) {
      const fd = new FormData();
      fd.append("file", f);
      try {
        const res = await fetch(`/api/work/attachments?taskId=${taskId}`, { method: "POST", body: fd });
        if (!res.ok) {
          const body = await res.json().catch(() => ({}));
          alert(`Upload failed for "${f.name}": ${body.error ?? `HTTP ${res.status}`}`);
        }
      } catch {
        alert(`Upload failed for "${f.name}" — network error.`);
      }
    }
    setUploading(false);
    if (fileRef.current) fileRef.current.value = "";
    await load();
    onChanged();
  }
  async function removeAttachment(id: string) {
    const res = await deleteAttachment(id);
    if (res.error) { alert(res.error); return; }
    await load();
    onChanged();
  }

  // Portaled to document.body — same admin Shell containing-block reason as
  // components/admin/BoardClient.tsx's own CardModal (a positioned ancestor
  // elsewhere in the shell would otherwise clip a fixed-position modal).
  return createPortal(
    <div className="fixed inset-0 z-50 flex items-start justify-center overflow-y-auto bg-black/60 p-4" onClick={onClose}>
      <div className="mt-8 w-full max-w-2xl rounded-2xl border border-white/10 bg-navy-900 p-5" onClick={(e) => e.stopPropagation()}>
        <div className="flex items-start justify-between gap-3">
          <div className="flex flex-1 items-center gap-2">
            <input
              type="checkbox"
              checked={!!task.completedAt}
              onChange={onToggleComplete}
              className="h-4 w-4"
              title={task.completedAt ? "Mark incomplete" : "Mark complete"}
            />
            <input
              className={`input flex-1 text-lg font-semibold ${task.completedAt ? "text-slate-500 line-through" : ""}`}
              defaultValue={task.title}
              onBlur={(e) => saveTitle(e.target.value)}
            />
          </div>
          <button className="text-slate-400 hover:text-white" onClick={onClose}>✕</button>
        </div>

        <div className="mt-3 flex flex-wrap gap-3 text-sm">
          <label className="flex items-center gap-1.5 text-slate-400">
            Priority
            <select className="input py-1 text-xs" value={task.priority} onChange={(e) => onPriorityChange(e.target.value)}>
              {PRIORITIES.map((p) => <option key={p} value={p}>{p.toLowerCase()}</option>)}
            </select>
          </label>
          <label className="flex items-center gap-1.5 text-slate-400">
            Assignee
            <select className="input py-1 text-xs" value={task.assigneeId ?? ""} onChange={(e) => onAssigneeChange(e.target.value)}>
              <option value="">— unassigned —</option>
              {assignableUsers.map((u) => <option key={u.id} value={u.id}>{u.name}</option>)}
            </select>
          </label>
          <label className="flex items-center gap-1.5 text-slate-400">
            Due
            <input
              type="date"
              className="input py-1 text-xs"
              defaultValue={task.dueAt ? task.dueAt.slice(0, 10) : ""}
              onBlur={(e) => onDueChange(e.target.value)}
            />
          </label>
        </div>

        <div className="mt-4">
          <p className="mb-1 text-xs font-medium text-slate-400">Description</p>
          <textarea
            className="input text-sm"
            rows={4}
            value={desc}
            onChange={(e) => setDesc(e.target.value)}
            onBlur={saveDescription}
            placeholder="Details, links, context…"
          />
        </div>

        <div className="mt-4">
          <p className="mb-1 text-xs font-medium text-slate-400">
            Checklist{task.checklistTotal > 0 ? ` (${task.checklistDone}/${task.checklistTotal})` : ""}
          </p>
          <div className="space-y-1">
            {task.checklist.map((c) => (
              <div key={c.id} className="flex items-center gap-2 text-sm">
                <input type="checkbox" checked={c.done} onChange={(e) => toggleItem(c.id, e.target.checked)} />
                <span className={c.done ? "flex-1 text-slate-500 line-through" : "flex-1 text-slate-200"}>{c.label}</span>
                <button className="text-xs text-slate-600 hover:text-red-400" onClick={() => removeItem(c.id)}>✕</button>
              </div>
            ))}
          </div>
          <div className="mt-2 flex gap-2">
            <input
              className="input text-sm"
              placeholder="Add checklist item…"
              value={checklistLabel}
              onChange={(e) => setChecklistLabel(e.target.value)}
              onKeyDown={(e) => { if (e.key === "Enter") addItem(); }}
            />
          </div>
        </div>

        <div className="mt-4">
          <div className="mb-1 flex items-center justify-between">
            <p className="text-xs font-medium text-slate-400">Attachments</p>
            <button className="text-xs text-brand-300 hover:underline" onClick={() => fileRef.current?.click()}>
              {uploading ? "Uploading…" : "+ Add file"}
            </button>
            <input ref={fileRef} type="file" multiple className="hidden" onChange={(e) => uploadFiles(Array.from(e.target.files ?? []))} />
          </div>
          <div className="grid grid-cols-2 gap-2">
            {task.attachments.map((a) => (
              <div key={a.id} className="rounded-lg border border-white/[0.06] bg-white/[0.02] p-2">
                {a.kind === "IMAGE" ? (
                  <a href={a.url} target="_blank" rel="noreferrer">
                    <img src={a.url} alt={a.filename} className="max-h-40 w-full rounded object-cover" />
                  </a>
                ) : a.kind === "VIDEO" ? (
                  <video src={a.url} controls className="max-h-40 w-full rounded" />
                ) : (
                  <a href={a.url} target="_blank" rel="noreferrer" className="block truncate text-sm text-brand-300 hover:underline">
                    📄 {a.filename}
                  </a>
                )}
                <div className="mt-1 flex items-center justify-between text-[11px] text-slate-500">
                  <span className="truncate">{a.filename} · {(a.sizeBytes / 1024 / 1024).toFixed(1)} MB · {a.uploadedByName}</span>
                  <button className="text-red-400 hover:underline" onClick={() => removeAttachment(a.id)}>remove</button>
                </div>
              </div>
            ))}
          </div>
        </div>

        <div className="mt-4">
          <p className="mb-1 text-xs font-medium text-slate-400">Comments</p>
          <div className="space-y-2">
            {task.comments.map((m) => (
              <div key={m.id} className="rounded-lg bg-white/[0.03] px-3 py-2 text-sm">
                <div className="flex items-center justify-between">
                  <span className="text-xs text-slate-500">{m.authorName} · {new Date(m.createdAt).toLocaleString()}</span>
                  <button className="text-[11px] text-slate-600 hover:text-red-400" onClick={() => removeComment(m.id)}>delete</button>
                </div>
                <p className="whitespace-pre-wrap text-slate-200">{m.body}</p>
              </div>
            ))}
          </div>
          <div className="mt-2 flex gap-2">
            <input
              className="input text-sm"
              placeholder="Add a comment…"
              value={comment}
              onChange={(e) => setComment(e.target.value)}
              onKeyDown={(e) => { if (e.key === "Enter") postComment(); }}
            />
          </div>
        </div>

        <div className="mt-5 flex justify-end">
          <button className="text-xs text-slate-400 hover:text-slate-200 hover:underline" onClick={onArchive}>Archive task</button>
        </div>
      </div>
    </div>,
    document.body,
  );
}

"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import {
  createBoard,
  renameBoard,
  archiveBoard,
  type WorkBoardSummary,
  type WorkBoardData,
  type AssignableUser,
  type WorkActivityEntry,
} from "@/lib/actions-work";
import { WorkBoardClient } from "./WorkBoardClient";

/**
 * Board picker + (admin-only) activity tab, shared verbatim between
 * app/admin/tasks/page.tsx and app/staff/tasks/page.tsx. The Kanban itself
 * lives in WorkBoardClient — this component is only the chrome around it:
 * which board is selected and, for admins, the task.* audit feed.
 */
export function WorkBoardsView({
  portal,
  boards,
  activeBoardId,
  board,
  initialTaskId,
  assignableUsers,
  activity,
}: {
  portal: "admin" | "staff";
  boards: WorkBoardSummary[];
  activeBoardId: string;
  board: WorkBoardData | null;
  initialTaskId?: string | null;
  assignableUsers: AssignableUser[];
  /** Only ever passed by the admin page — the plan scopes the Activity tab to
   *  /admin/tasks. */
  activity?: WorkActivityEntry[];
}) {
  const router = useRouter();
  const [tab, setTab] = useState<"board" | "activity">("board");
  const base = portal === "admin" ? "/admin/tasks" : "/staff/tasks";
  const showActivityTab = portal === "admin" && activity !== undefined;

  async function newBoard() {
    const name = prompt("New board name (e.g. Marketing, Support ops)");
    if (!name?.trim()) return;
    const res = await createBoard(name.trim());
    if (res.id) router.push(`${base}?board=${res.id}`);
    else if (res.error) alert(res.error);
  }

  async function rename(id: string, current: string) {
    const name = prompt("Rename board", current);
    if (!name?.trim() || name.trim() === current) return;
    await renameBoard(id, name.trim());
    router.refresh();
  }

  async function archive(id: string) {
    if (!confirm("Archive this board? (hides it, keeps its columns and tasks)")) return;
    await archiveBoard(id);
    router.push(base);
  }

  return (
    <div className="flex h-[calc(100vh-4.5rem)] flex-col gap-3 px-4 py-4 sm:px-6">
      <div className="flex flex-shrink-0 flex-wrap items-center gap-1.5">
        {boards.map((b) => (
          <a
            key={b.id}
            href={`${base}?board=${b.id}`}
            onDoubleClick={(e) => { e.preventDefault(); rename(b.id, b.name); }}
            className={`rounded-lg px-2.5 py-1 text-sm ${b.id === activeBoardId ? "bg-brand-500/20 text-brand-100" : "text-slate-400 hover:bg-white/5"}`}
            title="Double-click to rename"
          >
            {b.name} <span className="text-xs text-slate-500">{b.taskCount}</span>
          </a>
        ))}
        <button onClick={newBoard} className="rounded-lg border border-white/10 px-2.5 py-1 text-sm text-slate-300 hover:bg-white/5">
          + Board
        </button>
        {board && (
          <button onClick={() => archive(board.id)} className="ml-1 text-xs text-slate-600 hover:text-red-400">
            archive board
          </button>
        )}

        {showActivityTab && (
          <div className="ml-auto flex items-center gap-1 rounded-lg border border-white/10 p-0.5">
            <button onClick={() => setTab("board")} className={`rounded px-2.5 py-1 text-xs ${tab === "board" ? "bg-white/10 text-white" : "text-slate-400"}`}>
              Board
            </button>
            <button onClick={() => setTab("activity")} className={`rounded px-2.5 py-1 text-xs ${tab === "activity" ? "bg-white/10 text-white" : "text-slate-400"}`}>
              Activity
            </button>
          </div>
        )}
      </div>

      {showActivityTab && tab === "activity" ? (
        <ActivityFeed entries={activity ?? []} />
      ) : board ? (
        <WorkBoardClient key={board.id} board={board} portal={portal} assignableUsers={assignableUsers} initialTaskId={initialTaskId} />
      ) : (
        <p className="text-sm text-slate-500">No boards yet — create one to get started.</p>
      )}
    </div>
  );
}

function ActivityFeed({ entries }: { entries: WorkActivityEntry[] }) {
  if (entries.length === 0) return <p className="text-sm text-slate-500">No task activity yet.</p>;
  return (
    <div className="flex-1 overflow-y-auto rounded-xl border border-white/[0.06] bg-white/[0.02]">
      <table className="w-full text-left text-sm">
        <thead className="border-b border-white/[0.06] text-xs uppercase tracking-wider text-slate-500">
          <tr>
            <th className="px-3 py-2">When</th>
            <th className="px-3 py-2">Who</th>
            <th className="px-3 py-2">Action</th>
            <th className="px-3 py-2">Detail</th>
          </tr>
        </thead>
        <tbody>
          {entries.map((e) => (
            <tr key={e.id} className="border-b border-white/[0.04] last:border-0">
              <td className="whitespace-nowrap px-3 py-2 text-slate-500">{new Date(e.createdAt).toLocaleString()}</td>
              <td className="px-3 py-2 text-slate-300">{e.userName}</td>
              <td className="px-3 py-2 font-mono text-xs text-brand-300">{e.action}</td>
              <td className="px-3 py-2 text-slate-400">{e.detail ?? ""}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

import { requireAreaOrGrant } from "@/lib/staff-grants";
import { listBoards, getBoard, listAssignableUsers, listTaskActivity } from "@/lib/actions-work";
import { WorkBoardsView } from "@/components/work/WorkBoardsView";

export const dynamic = "force-dynamic";

/**
 * Admin surface for the staff task/project system. `requireAreaOrGrant("tasks")`
 * lets SUPPORT/BILLING/ADMIN in unconditionally (AREA_ROLES.tasks in
 * lib/rbac.ts) and a Role.EMPLOYEE in only with an explicit StaffGrant — same
 * gate, same shared view, as app/staff/tasks/page.tsx. The only thing unique
 * to this route is the Activity tab (recent task.* AuditLog rows), which is
 * admin oversight over everything staff do here.
 */
export default async function AdminTasksPage({
  searchParams,
}: {
  searchParams: Promise<{ board?: string; task?: string }>;
}) {
  await requireAreaOrGrant("tasks");
  const sp = await searchParams;

  const boards = await listBoards();
  const activeBoardId = boards.find((b) => b.id === sp.board)?.id ?? boards[0]?.id ?? "";

  const [board, assignableUsers, activity] = await Promise.all([
    activeBoardId ? getBoard(activeBoardId) : Promise.resolve(null),
    listAssignableUsers(),
    listTaskActivity(),
  ]);

  return (
    <WorkBoardsView
      portal="admin"
      boards={boards}
      activeBoardId={activeBoardId}
      board={board}
      initialTaskId={sp.task ?? null}
      assignableUsers={assignableUsers}
      activity={activity}
    />
  );
}

